/* OFFGRID 180 service worker (generated by build.py). Cache-first: the whole app works offline. */
const CACHE = "offgrid180-dev-d2a451d3de";
const FILES = [
"app.css",
"icons/icon-192.png",
"icons/icon-512.png",
"icons/icon.svg",
"icons/maskable-512.png",
"icons/maskable.svg",
"index.html",
"js/app.js",
"js/calc.js",
"js/content/courses.js",
"js/content/diagrams.js",
"js/content/equipment.js",
"js/content/library1.js",
"js/content/library2.js",
"js/content/library3.js",
"js/content/modules.js",
"js/content/trees.js",
"js/db.js",
"js/status.js",
"js/ui.js",
"js/version.js",
"js/views/emergency.js",
"js/views/foodwater.js",
"js/views/home.js",
"js/views/inventory.js",
"js/views/library.js",
"js/views/maps.js",
"js/views/medical.js",
"js/views/ops.js",
"js/views/settings.js",
"js/views/training.js",
"manifest.webmanifest"
];
self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(['./'].concat(FILES))).then(() => self.skipWaiting()));
});
self.addEventListener('activate', e => {
  e.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(k => k.startsWith('offgrid180-') && k !== CACHE).map(k => caches.delete(k)))).then(() => self.clients.claim()));
});
self.addEventListener('fetch', e => {
  const url = new URL(e.request.url);
  if (e.request.method !== 'GET' || url.origin !== location.origin) return; // optional online features (forecast) go straight to network
  e.respondWith(caches.match(e.request, { ignoreSearch: true }).then(hit => hit || fetch(e.request).then(res => {
    if (res.ok) { const copy = res.clone(); caches.open(CACHE).then(c => c.put(e.request, copy)); }
    return res;
  }).catch(() => caches.match('./index.html'))));
});
